// APRS symbol artwork: APRSdroid (https://github.com/ge0rg/aprsdroid), GPL-2.0, aprs.fi symbol set.
// Bitmaps are generated by tools/gen_aprs_icons.py into ../icons/aprs/.
#include "aprs_icon.h"

#include "../icons/aprs/aprs_icons.h"

const lv_image_dsc_t* aprsIconImage(AprsIcon icon, int px) {
  if (icon == AprsIcon::None) return nullptr;
  const lv_image_dsc_t* const* set = px <= 16 ? aprs_icons_16 : px <= 24 ? aprs_icons_24 : aprs_icons_32;
  return set[(int)icon - 1];
}
